<?php
namespace NexoCursos;
defined('ABSPATH') || exit;
final class PortalPeople {
    public static function mutate(string $action,array $d) {
        if($action==='team_save'){return self::team_save($d);}
        $course=Portal::id($d,'course_id');$c=Portal::course($course);if(is_wp_error($c)){return $c;}
        $date=Portal::text($d,'enrolled_on');if(in_array($action,['student_create','enrollment'],true)&&$date&&(!Calendar::date($date)||$date>wp_date('Y-m-d'))){return new \WP_Error('date','Informe uma data de matrícula válida, até hoje.');}
        if($action==='student_create'){
            $password=wp_generate_password(32,true);$user=Commerce::create_student(['full_name'=>Portal::text($d,'full_name'),'user_email'=>Portal::text($d,'email'),'user_password'=>$password,'password_confirm'=>$password]);
            if(is_wp_error($user)){return new \WP_Error('student','Não foi possível criar o aluno. Confira nome e e-mail. Se a conta já existe, faça a matrícula pelo e-mail.');}
            $r=Core::enroll($user->ID,$course);if(is_wp_error($r)){return $r;}self::enrollment_date($user->ID,$course,Portal::text($d,'enrolled_on'));
            if(!empty($d['send_invite'])){wp_new_user_notification($user->ID,null,'user');}
            return ['message'=>'Aluno criado e matriculado.'.(!empty($d['send_invite'])?' O link de acesso foi solicitado por e-mail.':''),'view'=>'students','args'=>['course_id'=>$course,'student_id'=>$user->ID]];
        }
        $identifier=Portal::text($d,'student');$uid=Portal::id($d,'student_id');$user=$uid?get_userdata($uid):(is_email($identifier)?get_user_by('email',$identifier):false);
        if(!$user){return new \WP_Error('student','Aluno não encontrado. Cadastre uma nova conta ou confira o e-mail.');}
        if($action==='legacy_attendance'){
            $date=Portal::text($d,'attendance_date');if(get_post_meta($course,'_nexo_mode',true)==='erp'||!isset(Calendar::enrolled($course)[$user->ID])||!Calendar::date($date)||$date>wp_date('Y-m-d')){return new \WP_Error('attendance','Escolha um aluno matriculado e uma data até hoje. Nos cursos presenciais, use a chamada por aula.');}
            $r=Core::set_attendance($course,$user->ID,$date,Portal::text($d,'attendance_status'));return is_wp_error($r)?$r:['message'=>'Presença por data salva.','view'=>'students','args'=>['course_id'=>$course,'student_id'=>$user->ID]];
        }
        if($action==='student_profile'){
            if(!Portal::all_courses()||!self::belongs($course,$user->ID)||!self::student_role($user)){return new \WP_Error('forbidden','Você não pode alterar este cadastro.');}
            $name=Portal::text($d,'full_name');if(!$name){return new \WP_Error('name','Informe o nome do aluno.');}$r=wp_update_user(['ID'=>$user->ID,'display_name'=>mb_substr($name,0,120),'first_name'=>mb_substr($name,0,120)]);if(is_wp_error($r)){return $r;}return ['message'=>'Nome do aluno atualizado. E-mail, senha e permissões foram mantidos.','view'=>'students','args'=>['course_id'=>$course,'student_id'=>$user->ID]];
        }
        $operation=Portal::text($d,'operation');if(!in_array($operation,['enroll','revoke'],true)){return new \WP_Error('operation','Operação inválida.');}
        if(!self::student_role($user)&&!Portal::all_courses()){return new \WP_Error('student','Esta conta pertence à equipe. Peça à coordenação para matriculá-la.');}
        $existing=false;foreach(Core::enrollments($course) as $row){if((int)$row->user_id===$user->ID&&(int)$row->order_id===0){$existing=true;break;}}
        $r=$operation==='revoke'?Core::revoke($user->ID,$course,0):Core::enroll($user->ID,$course);if(is_wp_error($r)||!$r){return is_wp_error($r)?$r:new \WP_Error('enroll','Não foi possível salvar a matrícula.');}
        if($operation==='enroll'&&!$existing){self::enrollment_date($user->ID,$course,Portal::text($d,'enrolled_on'));}
        return ['message'=>$operation==='revoke'?'Matrícula manual removida. Acesso por compras válidas foi preservado.':'Matrícula manual adicionada.','view'=>'students','args'=>['course_id'=>$course]];
    }
    private static function enrollment_date(int $uid,int $course,string $date): void {
        $at=Calendar::date($date);if(!$at||$date>wp_date('Y-m-d')){return;}global $wpdb;$wpdb->update($wpdb->prefix.'nexo_enrollments',['created_at'=>$at->setTimezone(new \DateTimeZone('UTC'))->format('Y-m-d H:i:s')],['user_id'=>$uid,'course_id'=>$course,'order_id'=>0],['%s'],['%d','%d','%d']);
    }
    public static function student_role(\WP_User $user): bool {return !user_can($user,'manage_options')&&!user_can($user,'edit_users')&&!user_can($user,'manage_woocommerce')&&!Portal::allowed($user->ID);}
    public static function belongs(int $course,int $uid): bool {foreach(Core::enrollments($course) as $r){if((int)$r->user_id===$uid){return true;}}return false;}
    public static function render(): void {
        $courses=Portal::courses();$selected=Portal::id($_GET,'course_id');if($selected&&is_wp_error(Portal::course($selected))){echo '<p class="np-error">Curso indisponível.</p>';return;}
        if(!$courses){echo '<p class="np-empty">Nenhum curso atribuído para gerenciar alunos.</p>';return;}$uid=Portal::id($_GET,'student_id');if($uid&&$selected){self::detail($selected,$uid);return;}
        $options=[0=>'Todos os meus cursos'];foreach($courses as $c){$options[$c->ID]=$c->post_title;}
        echo '<form method="get" action="'.esc_url(nexo_page_url('dashboard')).'" class="np-filters">'.Portal::get_fields('students').Portal::select('Curso','course_id',$options,$selected).Portal::input('Buscar aluno','student_search',Portal::text($_GET,'student_search'),'search').Portal::button('Filtrar','np-secondary').'</form>';
        $rows=[];$search=mb_strtolower(Portal::text($_GET,'student_search'));foreach($courses as $c){if($selected&&$c->ID!==$selected){continue;}foreach(Core::enrollments($c->ID) as $r){$user=get_userdata((int)$r->user_id);if(!$user){continue;}if($search&&!str_contains(mb_strtolower($user->display_name.' '.$user->user_email),$search)){continue;}$key=$c->ID.':'.$user->ID;if(!isset($rows[$key])){$rows[$key]=['course'=>$c,'user'=>$user,'active'=>false,'manual'=>false];}if($r->status==='active'){$rows[$key]['active']=true;if((int)$r->order_id===0){$rows[$key]['manual']=true;}}}}
        $page=max(1,Portal::id($_GET,'students_page'));$pages=max(1,(int)ceil(count($rows)/30));$page=min($page,$pages);echo '<div class="np-students-list">';
        foreach(array_slice(array_values($rows),($page-1)*30,30) as $row){$user=$row['user'];$course=$row['course'];$progress=Core::progress($course->ID,$user->ID);echo '<article class="np-card np-student"><div class="np-initial" aria-hidden="true">'.esc_html(mb_substr($user->display_name,0,1)).'</div><div><span class="np-badge">'.($row['active']?'Matrícula ativa':'Matrícula encerrada').'</span><h2>'.esc_html($user->display_name).'</h2><p class="np-break">'.esc_html($user->user_email).'</p><p>'.esc_html($course->post_title).'</p>'.(get_post_meta($course->ID,'_nexo_mode',true)!=='erp'?'<p>Progresso: '.absint($progress['percent']).'%</p>':'').'<div class="np-actions"><a class="np-button np-secondary" href="'.esc_url(Portal::url('students',['course_id'=>$course->ID,'student_id'=>$user->ID])).'">Ver acompanhamento</a>';if($row['manual']){echo Portal::form('enrollment','students',['course_id'=>$course->ID,'student_id'=>$user->ID,'operation'=>'revoke']).Portal::button('Remover matrícula manual','np-quiet').'</form>';}echo '</div></div></article>';}
        echo '</div>';if(!$rows){echo '<p class="np-empty">Nenhum aluno encontrado.</p>';}if($pages>1){echo '<nav class="np-pagination" aria-label="Páginas de alunos">';for($i=max(1,$page-2);$i<=min($pages,$page+2);$i++){echo '<a '.($i===$page?'aria-current="page"':'').' href="'.esc_url(Portal::url('students',['course_id'=>$selected,'student_search'=>$search,'students_page'=>$i])).'">'.$i.'</a>';}echo '</nav>';}
        unset($options[0]);$enroll_course=$selected?:array_key_first($options);
        echo '<div class="np-two-columns"><section class="np-card"><h2>Matricular uma conta existente</h2>'.Portal::form('enrollment','students',['operation'=>'enroll']).Portal::select('Curso','course_id',$options,$enroll_course).Portal::input('E-mail do aluno','student','','email','required autocomplete="off"').Portal::input('Data da matrícula','enrolled_on',wp_date('Y-m-d'),'date','max="'.esc_attr(wp_date('Y-m-d')).'"').Portal::button('Matricular aluno').'<p class="np-help">Matrículas por compra são mantidas separadamente.</p></form></section><section class="np-card"><h2>Cadastrar e matricular novo aluno</h2>'.Portal::form('student_create','students').Portal::select('Curso','course_id',$options,$enroll_course).Portal::input('Nome completo','full_name','','text','required maxlength="120" autocomplete="name"').Portal::input('E-mail','email','','email','required autocomplete="email"').Portal::input('Data da matrícula','enrolled_on',wp_date('Y-m-d'),'date','max="'.esc_attr(wp_date('Y-m-d')).'"').'<label class="np-check"><input type="checkbox" name="send_invite" value="1" checked> Enviar e-mail para o aluno definir sua senha</label>'.Portal::button('Cadastrar aluno').'</form></section></div>';
    }
    private static function detail(int $course,int $uid): void {
        $user=get_userdata($uid);if(!$user||!self::belongs($course,$uid)){echo '<p class="np-error">Aluno indisponível para este curso.</p>';return;}
        echo '<a class="np-back" href="'.esc_url(Portal::url('students',['course_id'=>$course])).'">← Alunos do curso</a><section class="np-card"><h2>'.esc_html($user->display_name).'</h2><p class="np-break">'.esc_html($user->user_email).'</p><p>'.esc_html(get_the_title($course)).'</p>';
        $progress=Core::progress($course,$uid);if(get_post_meta($course,'_nexo_mode',true)!=='erp'){echo '<p>Progresso de aprendizagem: <strong>'.absint($progress['percent']).'%</strong></p>';}
        $summary=Calendar::summary($course);$counts=$summary['students'][$uid]??['present'=>0,'absent'=>0,'excused'=>0,'pending'=>0];$pct=Calendar::percentage($counts);$coverage=Calendar::coverage($counts);echo '<div class="np-kpis"><article class="np-kpi"><span>Frequência registrada</span><strong>'.($pct===null?'—':$pct.'%').'</strong></article><article class="np-kpi"><span>Cobertura da chamada</span><strong>'.($coverage===null?'—':$coverage.'%').'</strong></article></div></section>';
        $sessions=Calendar::sessions($course);if($sessions){$marks=[];foreach(Calendar::marks($course) as $r){if((int)$r->user_id===$uid){$marks[(int)$r->session_id]=$r->status;}}echo '<section class="np-card"><h2>Histórico de presença</h2><div class="np-table-wrap"><table class="np-table"><thead><tr><th>Aula</th><th>Data</th><th>Presença</th><th>Ação</th></tr></thead><tbody>';$joined=Calendar::enrolled($course)[$uid]??null;foreach($sessions as $s){$label=$s['status']==='cancelled'?'Cancelada':(($joined&&!Calendar::eligible($s,$joined))?'Anterior à matrícula':(['present'=>'Presente','absent'=>'Ausente','excused'=>'Justificada'][$marks[$s['id']]??'']??'Pendente'));echo '<tr><td>'.esc_html($s['title']).'</td><td>'.esc_html(Calendar::date($s['date'])->format('d/m/Y')).'</td><td>'.esc_html($label).'</td><td><a class="np-text-link" href="'.esc_url(Portal::url('classroom',['course_id'=>$course,'nexo_session'=>$s['id']])).'">Abrir chamada</a></td></tr>';}echo '</tbody></table></div></section>';}
        $legacy=Core::attendance($course,$uid);$online=get_post_meta($course,'_nexo_mode',true)!=='erp';if($legacy||$online){echo '<details class="np-card np-settings-section"><summary>Registros de presença por data</summary>';if($legacy){echo '<table class="np-table"><thead><tr><th>Data</th><th>Presença</th></tr></thead><tbody>';foreach($legacy as $date=>$status){echo '<tr><td>'.esc_html($date).'</td><td>'.esc_html(['present'=>'Presente','absent'=>'Ausente','excused'=>'Justificada'][$status]??$status).'</td></tr>';}echo '</tbody></table>';}if($online&&isset(Calendar::enrolled($course)[$uid])){echo Portal::form('legacy_attendance','students',['course_id'=>$course,'student_id'=>$uid]).Portal::input('Data','attendance_date',wp_date('Y-m-d'),'date','required max="'.esc_attr(wp_date('Y-m-d')).'"').Portal::select('Presença','attendance_status',['present'=>'Presente','absent'=>'Ausente','excused'=>'Justificada'],'present').Portal::button('Salvar presença por data','np-secondary').'</form>';}echo '</details>';}
        if(Portal::all_courses()&&self::student_role($user)){echo '<section class="np-card"><h2>Dados do aluno</h2>'.Portal::form('student_profile','students',['course_id'=>$course,'student_id'=>$uid]).Portal::input('Nome completo','full_name',$user->display_name,'text','required maxlength="120"').Portal::button('Salvar nome').'<p class="np-help">E-mail, senha e permissões da conta são mantidos.</p></form></section>';}
    }
    private static function team_save(array $d) {
        if(!current_user_can('manage_options')){return new \WP_Error('forbidden','Somente o administrador pode definir os acessos da equipe.');}
        $id=Portal::id($d,'member_id');$user=$id?get_userdata($id):null;$roles=['subscriber'=>'Aluno','nexo_manager'=>'Gerente de cursos','nexo_coordinator'=>'Coordenador da plataforma'];if(get_role('shop_manager')){$roles['shop_manager']='Gerente da loja';}$role=Portal::text($d,'role');$name=Portal::text($d,'full_name');
        if(!$name||!isset($roles[$role])||($id&&(!$user||user_can($user,'manage_options')))){return new \WP_Error('team','Confira os dados. Contas de administrador são preservadas.');}
        if(!$id){$email=sanitize_email(Portal::text($d,'email'));if(!is_email($email)||email_exists($email)){return new \WP_Error('email','Informe um e-mail válido que ainda não possua conta.');}$id=wp_insert_user(['user_login'=>'equipe_'.strtolower(wp_generate_password(16,false,false)),'user_pass'=>wp_generate_password(32,true),'user_email'=>$email,'display_name'=>mb_substr($name,0,120),'role'=>$role]);if(is_wp_error($id)){return $id;}if(!empty($d['send_invite'])){wp_new_user_notification($id,null,'user');}}
        else{$r=wp_update_user(['ID'=>$id,'display_name'=>mb_substr($name,0,120),'role'=>$role]);if(is_wp_error($r)){return $r;}}
        return ['message'=>'Acesso da equipe atualizado. Gerentes precisam ser atribuídos aos cursos.','view'=>'team'];
    }
    public static function team(): void {
        if(!current_user_can('manage_options')){echo '<p class="np-error">Área exclusiva do administrador.</p>';return;}
        echo '<p class="np-lead">Gerentes cuidam dos cursos atribuídos. A coordenação pode gerenciar todos os cursos, a identidade e as vendas. O acesso ao painel WordPress continua exclusivo do administrador.</p><div class="np-stack">';
        echo '<form method="get" action="'.esc_url(nexo_page_url('dashboard')).'" class="np-filters">'.Portal::get_fields('team').Portal::input('Localizar uma conta existente pelo e-mail','team_email',Portal::text($_GET,'team_email'),'email').Portal::button('Localizar pessoa','np-secondary').'</form>';
        $page=max(1,Portal::id($_GET,'team_page'));$query=new \WP_User_Query(['role__in'=>['nexo_manager','nexo_coordinator','shop_manager'],'number'=>50,'paged'=>$page,'orderby'=>'display_name']);$members=[];foreach($query->get_results() as $member){$members[$member->ID]=$member;}$email=sanitize_email(Portal::text($_GET,'team_email'));if($email){$found=get_user_by('email',$email);if($found&&!user_can($found,'manage_options')){$members=[$found->ID=>$found];}else{echo '<p>Nenhuma conta editável encontrada com esse e-mail.</p>';}}
        foreach($members as $u){if(user_can($u,'manage_options')){continue;}echo '<article class="np-card"><h2>'.esc_html($u->display_name).'</h2><p class="np-break">'.esc_html($u->user_email).'</p>'.Portal::form('team_save','team',['member_id'=>$u->ID]).'<div class="np-form-grid">'.Portal::input('Nome','full_name',$u->display_name,'text','required').Portal::select('Perfil','role',['subscriber'=>'Aluno','nexo_manager'=>'Gerente dos cursos atribuídos','nexo_coordinator'=>'Coordenação — todos os cursos e vendas']+(get_role('shop_manager')?['shop_manager'=>'Gerente da loja — todos os pedidos']:[]),$u->roles[0]??'nexo_manager').'</div>'.Portal::button('Salvar acesso','np-secondary').'</form></article>';}
        echo '</div>';if(!$email&&$query->get_total()>50){echo '<nav class="np-pagination">';for($i=max(1,$page-2);$i<=min((int)ceil($query->get_total()/50),$page+2);$i++){echo '<a href="'.esc_url(Portal::url('team',['team_page'=>$i])).'">'.$i.'</a>';}echo '</nav>';}echo '<section class="np-card"><h2>Adicionar pessoa à equipe</h2>'.Portal::form('team_save','team').'<div class="np-form-grid">'.Portal::input('Nome completo','full_name','','text','required maxlength="120"').Portal::input('E-mail','email','','email','required').Portal::select('Perfil','role',['nexo_manager'=>'Gerente dos cursos atribuídos','nexo_coordinator'=>'Coordenação — todos os cursos e vendas']+(get_role('shop_manager')?['shop_manager'=>'Gerente da loja — todos os pedidos']:[]),'nexo_manager').'</div><label class="np-check"><input type="checkbox" name="send_invite" value="1" checked> Enviar link para definir a senha</label>'.Portal::button('Adicionar à equipe').'</form></section>';
    }
}
